const OPTION_IDS = ['A', 'B', 'C', 'D'] as const

export const COA201_QUESTIONS: CbtQuestion[] = RAW_COA_QUESTIONS.map(
  ([num, topic, topicName, partName, sectionName, question, opts, answer]) => {
    const answerIdx = OPTION_IDS.indexOf(answer)
    const correctText = opts[answerIdx] ?? ''
    return {
      id: `coa-q${num}`,
      subjectCode: 'COA-201',
      subjectName: 'Computer Organization & Architecture',
      semester: 3,
      category: 'core',
      topic,
      topicName,
      partName,
      sectionName,
      question,
      type: 'single',
      options: OPTION_IDS.map((id, idx) => ({ id, text: opts[idx] })),
      correctAnswers: [answer],
      explanation: `Correct Answer: (${answer}) ${correctText}.`,
      difficulty: 'medium',
      status: 'approved'
    }
  }
)
